def transform(grid):
    pts={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: pts.setdefault(v,[]).append((r,c))
    if not pts:return [row[:] for row in grid]
    boxes={v:(min(r for r,c in p),min(c for r,c in p),max(r for r,c in p),max(c for r,c in p)) for v,p in pts.items()}
    v=min(boxes,key=lambda v:(boxes[v][2]-boxes[v][0]+1)*(boxes[v][3]-boxes[v][1]+1))
    a,b,d,e=boxes[v]
    inside=all(x<=a and y<=b and z>=d and w>=e for k,(x,y,z,w) in boxes.items() if k!=v)
    contains=any(grid[r][c] not in (0,v) for r in range(a,d+1) for c in range(b,e+1))
    return [[0 if x==v and not inside and not contains else x for x in row] for row in grid]

